def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find full-width and full-height separator stripes.
    rs = [r for r in range(h) if len(set(grid[r])) <= 2]
    cs = [c for c in range(w) if len({grid[r][c] for r in range(h)}) <= 2]

    # Retain the regularly spaced stripe coordinates.
    def regular_positions(items):
        if len(items) < 2:
            return items
        gaps = [b - a for a, b in zip(items, items[1:])]
        step = max(set(gaps), key=gaps.count)
        return [p for p in items if (p - items[0]) % step == 0]

    rs = regular_positions(rs)
    cs = regular_positions(cs)
    nr, nc = max(1, len(rs) - 1), max(1, len(cs) - 1)

    # The repeating interior color is the output background.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    out = [[background for _ in range(nc)] for _ in range(nr)]

    # Colored marks on separator intersections become output cells.
    for i, r in enumerate(rs[:nr]):
        for j, c in enumerate(cs[:nc]):
            v = grid[r][c]
            if v != background:
                out[i][j] = v
    return out
