def transform(grid):
    h, w = len(grid), len(grid[0])

    # Repeated solid stripes mark the grid's lattice.
    rows = [r for r in range(h) if len(set(grid[r])) <= 2]
    cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) <= 2]

    def main_gap(pos):
        gaps = [b - a for a, b in zip(pos, pos[1:])]
        return max(set(gaps), key=gaps.count) if gaps else 1

    dr, dc = main_gap(rows), main_gap(cols)
    rows = [r for r in rows if (r - rows[0]) % dr == 0]
    cols = [c for c in cols if (c - cols[0]) % dc == 0]

    # Output background is the color filling the lattice cells, not the stripes.
    counts = {}
    for r in range(h):
        for c in range(w):
            if r not in rows and c not in cols:
                v = grid[r][c]
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    nr, nc = len(rows) - 1, len(cols) - 1
    nr, nc = max(1, nr), max(1, nc)
    out = [[background for _ in range(nc)] for _ in range(nr)]

    # The most common color on the stripe intersections is the ordinary line color;
    # uncommon intersection colors encode the output marks.
    vals = [grid[r][c] for r in rows[:nr] for c in cols[:nc]]
    freq = {v: vals.count(v) for v in set(vals)}
    stripe_color = max(freq, key=freq.get)
    for i, r in enumerate(rows[:nr]):
        for j, c in enumerate(cols[:nc]):
            v = grid[r][c]
            if v != stripe_color:
                out[i][j] = v
    return out
